/**
 * Astro content collection for pSEO pages.
 *
 * Each entry under src/content/pseo/ is generated by scripts/pseo-generate.py
 * and consumed by src/pages/[bucket]/[slug].astro. Schema MUST stay
 * backward-compatible — Variant-B fields are optional so old records render.
 */
import { defineCollection, z } from 'astro:content';
import { glob } from 'astro/loaders';

const pseo = defineCollection({
  loader: glob({ pattern: '**/*.md', base: './src/content/pseo' }),
  schema: z.object({
    title: z.string(),
    description: z.string(),
    h1: z.string(),
    slug: z.string(),
    bucket: z.string(),
    // Y50 P0-1: affiliate program this page's generic CTAs point at. Unset =>
    // resolved from config/availability.yaml, so geo pages for jurisdictions
    // without ether.fi route to the fallback partner instead of a card the
    // reader cannot obtain.
    primary_partner: z.string().optional(),
    primary_keyword: z.string(),
    supporting_keywords: z.array(z.string()).default([]),
    intro_paragraph: z.string(),
    // AEO-4 cohort. Absent on the 544 pages that predate the experiment; the
    // eight-week comparison joins slug -> variant from here, offline.
    intro_variant: z.enum(['disclosure_first', 'answer_first']).optional(),
    long_context_paragraph: z.string().optional().default(''),
    snapshot_bullets: z.array(z.string()).optional().default([]),
    stakes_bullets: z.array(z.string()).optional().default([]),
    what_to_watch: z.array(z.string()).optional().default([]),
    bottom_line: z.array(z.string()).optional().default([]),
    faq: z
      .array(z.object({ q: z.string(), a: z.string() }))
      .optional()
      .default([]),
    related_clusters: z.array(z.string()).optional().default([]),
    images: z
      .array(
        z.object({
          src: z.string(),
          alt: z.string(),
          credit_html: z.string().optional().default(''),
          query: z.string().optional().default(''),
        })
      )
      .optional()
      .default([]),
    schema_article: z.record(z.any()).optional(),
    schema_faq: z.record(z.any()).optional(),
    generated_at: z.union([z.string(), z.date()]).transform((v) =>
      v instanceof Date ? v.toISOString() : v
    ),
    model: z.string(),
    pattern: z.string(),
    // News-bucket only (optional for backward compat with hub/compare/etc.)
    // Populated by scripts/news-ingest.py — never by the static keyword
    // generator. Required for NewsArticle schema rendering + visible
    // source attribution on /news/<slug>/ pages.
    source_url: z.string().url().optional(),
    source_name: z.string().optional(),
    source_category: z.string().optional(),
    news_published_at: z.string().optional(),
  }),
});

/**
 * Videos collection — one entry per published YouTube short.
 *
 * JSON files live in src/content/videos/<youtube_id>.json and are written by
 * `scripts/sync-yt-videos.py` from `video-generator/state/published.db`
 * publish_log + per-render `output/.../script.json`. The sync runs first in
 * deploy.sh so every build picks up newly-published videos automatically.
 *
 * The `target_pseo_slug` field, when present, signals [bucket]/[slug] to
 * embed this video at the top of that article (cross-collection linking).
 * When absent, the video appears only on /videos/ + /videos/<id>/ pages.
 */
const videos = defineCollection({
  loader: glob({ pattern: '**/*.json', base: './src/content/videos' }),
  schema: z.object({
    id: z.string(),                    // YouTube video id
    platform: z.enum(['youtube', 'instagram', 'tiktok']).default('youtube'),
    title: z.string(),                 // 60-100 char headline
    description: z.string(),           // 1-2 sentence summary for video sitemap
    body: z.string().optional().default(''),
    topic_id: z.number().int(),
    topic_primary: z.string(),
    topic_category: z.string(),
    topic_class: z.enum(['VIRAL', 'TOFU', 'MOFU', 'BOFU']),
    duration_s: z.number().nullable().optional(),
    thumbnail_url: z.string().url(),
    youtube_url: z.string().url(),
    embed_url: z.string().url(),
    published_at: z.string(),
    target_pseo_slug: z.string().nullable().optional(),
    hashtags: z.array(z.string()).optional().default([]),
  }),
});

export const collections = { pseo, videos };
